-- Triggers on entry_exit_details. Safe to re-run (drops and re-creates them).
-- Run 01_tables.sql first. The triggers run as the login that creates them:
-- never delete that login while the triggers exist.

DELIMITER $$

-- Drop old trigger trg_eed_wa_ai if present
DROP TRIGGER IF EXISTS `trg_eed_wa_ai`$$

-- Trigger trg_eed_wa_ai (ENTRY, and EXIT if inserted already exited)
CREATE TRIGGER `trg_eed_wa_ai`
AFTER INSERT ON `entry_exit_details`
FOR EACH ROW
BEGIN
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
  IF NULLIF(TRIM(NEW.`phone_number`), '') IS NOT NULL THEN
    INSERT IGNORE INTO `wa_notification_queue`
      (`source_record_id`, `event_type`, `phone`, `next_attempt_at`, `created_at`, `updated_at`)
    VALUES (NEW.`id`, 'ENTRY', LEFT(TRIM(NEW.`phone_number`), 20),
            UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), UTC_TIMESTAMP(6));
    IF NEW.`exit_date` IS NOT NULL THEN
      INSERT IGNORE INTO `wa_notification_queue`
      (`source_record_id`, `event_type`, `phone`, `next_attempt_at`, `created_at`, `updated_at`)
    VALUES (NEW.`id`, 'EXIT', LEFT(TRIM(NEW.`phone_number`), 20),
            UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), UTC_TIMESTAMP(6));
    END IF;
  END IF;
END$$

-- Drop old trigger trg_eed_wa_au if present
DROP TRIGGER IF EXISTS `trg_eed_wa_au`$$

-- Trigger trg_eed_wa_au (EXIT when exit time goes NULL -> value)
CREATE TRIGGER `trg_eed_wa_au`
AFTER UPDATE ON `entry_exit_details`
FOR EACH ROW
BEGIN
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
  IF OLD.`exit_date` IS NULL AND NEW.`exit_date` IS NOT NULL
     AND NULLIF(TRIM(NEW.`phone_number`), '') IS NOT NULL THEN
    INSERT IGNORE INTO `wa_notification_queue`
      (`source_record_id`, `event_type`, `phone`, `next_attempt_at`, `created_at`, `updated_at`)
    VALUES (NEW.`id`, 'EXIT', LEFT(TRIM(NEW.`phone_number`), 20),
            UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), UTC_TIMESTAMP(6));
  END IF;
END$$

